        /*
         * Large JSON columns are written in separate compact updates.
         * This follows the reference V2/V3 format and lowers the risk of
         * "MySQL server has gone away" errors on local XAMPP installations.
         */
        $now = now();

        DB::table('module_library_items')->updateOrInsert(
            ['module_code' => 'MODELING-SIMULATION-BASIC-V2'],
            [
                'module_no' => 6,
                'title' => 'Modeling and Simulation',
                'year_level' => 'Year 1',
                'version_no' => 2,
                'version_name' => 'Modeling and Simulation Practice and MCQ Review',
                'version_code' => 'V2',
                'description' => 'Building computational models, discrete event simulation, Monte Carlo methods, and systems analysis. This version emphasizes code tracing, worked practice, debugging, MCQ reasoning, comparison of methods, and mastery evidence.',
                'estimated_minutes' => 640,
                'sort_order' => 17,
                'is_active' => true,
                'created_at' => $now,
                'updated_at' => $now,
            ]
        );

        DB::table('module_library_items')
            ->where('module_code', 'MODELING-SIMULATION-BASIC-V2')
            ->update([
                'content_sections' => json_encode($this->contentSections(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);

        DB::table('module_library_items')
            ->where('module_code', 'MODELING-SIMULATION-BASIC-V2')
            ->update([
                'mcq_questions' => json_encode($this->mcqQuestions(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);
    }

